      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <main id="main-content" role="main">
    <section class="wrap" aria-label="Internet penetration gaps overview">
      <header class="hero animate" aria-label="Title">
        <div class="kicker">Digital divide • 2023 estimates</div>
        <h1 class="title">Internet penetration gaps across income, age, and place</h1>
        <p class="subtitle">Each bar shows the within-region gap in internet use between advantaged and disadvantaged groups. Larger values indicate greater inequality (percentage-point gap).</p>
      </header>

      <section class="card chart-card" data-reveal aria-label="Chart section">
        <div class="chart-head">
          <h2>Gap magnitude by region and dimension</h2>
          <div class="legend-key" aria-label="Legend">
            <span class="key"><span class="swatch"></span><span>Gap (percentage points)</span></span>
            <span class="key"><span class="swatch neg"></span><span>Low-penetration regions (Sub-Saharan Africa, South Asia)</span></span>
          </div>
        </div>
        <p class="chart-note">Definitions: Income gap = Q5 (Highest) − Q1 (Lowest). Age gap = 15–24 − 65+. Urban–rural gap = Urban − Rural. Regions are shown from lowest to highest overall penetration.</p>
        <div class="chart-area">
          <canvas id="gapChart" role="img" aria-label="Grouped horizontal bar chart showing internet penetration gaps by income, age, and urban-rural setting for four world regions"></canvas>
        </div>
        <div class="foot" aria-label="Source notes">
          <div><strong>Unit:</strong> percentage points (pp).</div>
          <div><strong>Source:</strong> /app/benchmark/source_data.json (datasets: internet_by_income_quintile, internet_by_age_group, internet_by_urban_rural, internet_overall_by_region).</div>
        </div>
      </section>
    </section>
  </main>

  </main>
  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) {
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          revealObserver.unobserve(e.target);
        }
      });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) {
        console.error('Download failed:', e);
      }
      menu.style.display = '';
    }

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var canvas = document.getElementById(canvasId);
          if (!canvas) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
          canvas.setAttribute('role', 'img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart');
          var ctx = canvas.getContext('2d');
          var chart = new Chart(ctx, config);
          canvas.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (e) {
          console.error('Chart init failed:', e);
          return null;
        }
      }
    };

    var sourceData = null;
    var gapChart = null;

    function buildGapData(sd) {
      var overall = sd.internet_overall_by_region.data.slice();
      overall.sort(function(a,b){ return a.overall_penetration - b.overall_penetration; });
      var regions = overall.map(function(d){ return d.region; });
      var lowRegions = new Set(['Sub-Saharan Africa','South Asia']);

      function byRegion(list, regionField, valueField, region) {
        for (var i=0;i<list.length;i++) {
          if (list[i][regionField] === region) return list[i][valueField];
        }
        return null;
      }

      var income = sd.internet_by_income_quintile.data;
      var age = sd.internet_by_age_group.data;
      var ur = sd.internet_by_urban_rural.data;

      var incomeGap = [];
      var ageGap = [];
      var urGap = [];

      for (var r=0;r<regions.length;r++) {
        var region = regions[r];

        var q1 = null, q5 = null;
        for (var i=0;i<income.length;i++) {
          if (income[i].region !== region) continue;
          if (income[i].quintile === 'Q1 (Lowest)') q1 = income[i].penetration;
          if (income[i].quintile === 'Q5 (Highest)') q5 = income[i].penetration;
        }
        incomeGap.push(q5 - q1);

        var a15 = null, a65 = null;
        for (var j=0;j<age.length;j++) {
          if (age[j].region !== region) continue;
          if (age[j].age_group === '15-24') a15 = age[j].penetration;
          if (age[j].age_group === '65+') a65 = age[j].penetration;
        }
        ageGap.push(a15 - a65);

        var urban = null, rural = null;
        for (var k=0;k<ur.length;k++) {
          if (ur[k].region !== region) continue;
          if (ur[k].setting === 'Urban') urban = ur[k].penetration;
          if (ur[k].setting === 'Rural') rural = ur[k].penetration;
        }
        urGap.push(urban - rural);
      }

      return {
        regions: regions,
        incomeGap: incomeGap,
        ageGap: ageGap,
        urGap: urGap,
        lowRegions: lowRegions,
        overallLookup: overall.reduce(function(acc, d){ acc[d.region]=d.overall_penetration; return acc; }, {})
      };
    }

    function chartColors() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        text: isDark ? '#EDEDED' : '#0f172a',
        tick: isDark ? '#B0B0B0' : '#516074',
        grid: isDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.10)',
        bar: getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || (isDark ? '#3b82f6' : '#1d4ed8'),
        bar2: getComputedStyle(document.documentElement).getPropertyValue('--accent-secondary').trim() || (isDark ? '#8b5cf6' : '#6d28d9'),
        bar3: getComputedStyle(document.documentElement).getPropertyValue('--warning').trim() || (isDark ? '#f59e0b' : '#b45309'),
        highlight: getComputedStyle(document.documentElement).getPropertyValue('--negative').trim() || (isDark ? '#f43f5e' : '#be123c')
      };
    }

    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      if (!sourceData) return;

      var c = chartColors();
      var d = buildGapData(sourceData);

      var baseBar = function(datasetLabel, dataArr, color, order) {
        return {
          label: datasetLabel,
          data: dataArr,
          backgroundColor: d.regions.map(function(r){ return d.lowRegions.has(r) ? c.highlight : color; }),
          borderColor: d.regions.map(function(r){ return d.lowRegions.has(r) ? c.highlight : color; }),
          borderWidth: 0,
          borderRadius: 6,
          barThickness: 16,
          maxBarThickness: 18,
          categoryPercentage: 0.74,
          barPercentage: 0.9,
          order: order
        };
      };

      var config = {
        type: 'bar',
        data: {
          labels: d.regions.map(function(r){ return r + ' (overall ' + d.overallLookup[r] + '%)'; }),
          datasets: [
            baseBar('Income gap (Q5 − Q1)', d.incomeGap, c.bar, 1),
            baseBar('Age gap (15–24 − 65+)', d.ageGap, c.bar2, 2),
            baseBar('Urban–rural gap (Urban − Rural)', d.urGap, c.bar3, 3)
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          indexAxis: 'y',
          interaction: { mode: 'nearest', axis: 'y', intersect: false },
          plugins: {
            legend: {
              position: 'bottom',
              labels: {
                color: c.text,
                boxWidth: 14,
                boxHeight: 10,
                usePointStyle: false,
                padding: 16,
                font: { size: 12, family: 'Inter' }
              }
            },
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(ctx) {
                  var val = ctx.parsed.x;
                  return ctx.dataset.label + ': ' + val + ' pp';
                },
                afterBody: function(items) {
                  if (!items || !items.length) return;
                  var label = items[0].label;
                  if (label.indexOf('Sub-Saharan Africa') === 0 || label.indexOf('South Asia') === 0) {
                    return ['Highlighted: low-penetration regions'];
                  }
                  return;
                }
              }
            },
            title: {
              display: true,
              text: 'Within-region gaps (pp) — compare inequality dimensions at a glance',
              color: c.text,
              font: { size: 13, weight: '600', family: 'Inter' },
              padding: { top: 8, bottom: 10 }
            }
          },
          scales: {
            x: {
              min: 0,
              max: 80,
              title: {
                display: true,
                text: 'Gap (percentage points) — higher means greater divide',
                color: c.text,
                font: { size: 12, weight: '600', family: 'Inter' },
                padding: { top: 8 }
              },
              grid: { color: c.grid },
              ticks: {
                color: c.tick,
                callback: function(v){ return v + ' pp'; },
                font: { size: 11, family: 'Inter' }
              },
              border: { color: c.grid }
            },
            y: {
              title: {
                display: true,
                text: 'Region (overall penetration shown in parentheses)',
                color: c.text,
                font: { size: 12, weight: '600', family: 'Inter' },
                padding: { bottom: 6 }
              },
              grid: { display: false },
              ticks: {
                color: c.text,
                font: { size: 11, family: 'Inter' }
              },
              border: { color: c.grid }
            }
          }
        }
      };

      gapChart = ChartManager.safeInit('gapChart', config);
    }

    function onThemeChange() {
      buildCharts();
    }

    window.addEventListener('load', function() {
      fetch('/app/benchmark/source_data.json')
        .then(function(r){ return r.json(); })
        .then(function(sd){ sourceData = sd; buildCharts(); })
        .catch(function(e){ console.error('Failed to load data:', e); });
    });
  </script>
</body>
</html>
